<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/../lib/cam_bootstrap.php';
cam_security_headers();
$error=''; $notice='';
if(isset($_POST['login'])) {
    if(cam_admin_login(trim((string)($_POST['username']??'')),(string)($_POST['password']??''))) { session_regenerate_id(true); $_SESSION['cam_admin']=true; header('Location: /admin/'); exit; }
    $error='Tên đăng nhập hoặc mật khẩu không đúng.';
}
if(isset($_POST['logout'])) { cam_check_csrf(); session_destroy(); header('Location: /admin/'); exit; }
if(empty($_SESSION['cam_admin'])) { ?><!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>CAM Admin</title><style>body{font:15px system-ui;background:#07121f;color:#dceaf2;display:grid;place-items:center;min-height:100vh;margin:0}form{width:min(360px,85vw);background:#102235;padding:26px;border-radius:16px}input,button{box-sizing:border-box;width:100%;padding:12px;margin:7px 0;border-radius:9px;border:1px solid #345;background:#081727;color:#fff}button{background:#19b9c5;color:#041014;font-weight:800}.error{color:#ff8591}</style><form method="post"><h1>CAM Product Admin</h1><p>Quản lý database sản phẩm và quy trình.</p><input name="username" placeholder="Tên đăng nhập" autocomplete="username" required><input type="password" name="password" placeholder="Mật khẩu" autocomplete="current-password" required><button name="login">Đăng nhập</button><p class="error"><?=htmlspecialchars($error)?></p></form></html><?php exit; }

try { cam_seed_if_empty(); cam_promote_due_changes(); $pdo=cam_db(); } catch(Throwable $e) { http_response_code(503); exit('Database unavailable'); }
if(isset($_POST['cancel_pending'])) {
    cam_check_csrf(); $pendingId=(int)($_POST['pending_id']??0);
    $pdo->prepare("UPDATE cam_pending_changes SET status='cancelled' WHERE pending_id=? AND status='testing'")->execute([$pendingId]);
    $notice='Đã hủy bản thử nghiệm.';
}
if(isset($_POST['save_product'])) {
    cam_check_csrf();
    $id=(string)($_POST['id']??'');
    $stmt=$pdo->prepare('SELECT data_json,revision FROM cam_products WHERE id=?'); $stmt->execute([$id]); $row=$stmt->fetch();
    if($row) {
        $item=json_decode($row['data_json'],true)?:[];
        $fields=['name','family','flow','testPlan','engineeringTestPlan','dpmsTestPlan','fluxPartNumber','pastePartNumber','proflowPartNumber','stencilPartNumber','capacitorInfo','fluxCenter','setupProcess','commonIssues','operatorTips','note'];
        foreach($fields as $field) $item[$field]=trim((string)($_POST[$field]??''));
        $item['id']=$id; $item['updatedAt']=gmdate('c'); $json=json_encode($item,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
        $pdo->beginTransaction();
        try {
            $pdo->prepare("UPDATE cam_pending_changes SET status='cancelled' WHERE product_id=? AND status='testing'")->execute([$id]);
            $pdo->prepare("INSERT INTO cam_pending_changes(product_id,proposed_json,base_revision,status,effective_at,created_by,change_note) VALUES(?,?,?,'testing',DATE_ADD(NOW(),INTERVAL 24 HOUR),'admin',?)")->execute([$id,$json,(int)$row['revision'],trim((string)($_POST['change_note']??''))]);
            $pdo->commit(); $notice='Đã tạo bản thử nghiệm 24 giờ. Dữ liệu public chưa thay đổi và sẽ tự áp dụng sau thời hạn.';
        } catch(Throwable $e) { $pdo->rollBack(); $error='Không thể lưu thay đổi.'; }
    }
}
$selected=(string)($_GET['product']??'');
$products=$pdo->query('SELECT id,name,family,flow,revision,updated_at FROM cam_products ORDER BY name')->fetchAll();
$edit=null;
if($selected!==''){ $s=$pdo->prepare('SELECT data_json,revision FROM cam_products WHERE id=?');$s->execute([$selected]);$r=$s->fetch();if($r){$edit=json_decode($r['data_json'],true);$edit['_revision']=$r['revision'];}}
$pendingForSelected=null;
if($selected!==''){ $q=$pdo->prepare("SELECT * FROM cam_pending_changes WHERE product_id=? AND status='testing' ORDER BY pending_id DESC LIMIT 1");$q->execute([$selected]);$pendingForSelected=$q->fetch()?:null; if($pendingForSelected){$preview=json_decode($pendingForSelected['proposed_json'],true);if(is_array($preview)){$edit=array_merge($edit?:[],$preview);$edit['_revision']=$r['revision']??0;}} }
$pendingChanges=$pdo->query("SELECT p.pending_id,p.product_id,p.effective_at,p.change_note,c.name FROM cam_pending_changes p JOIN cam_products c ON c.id=p.product_id WHERE p.status='testing' ORDER BY p.effective_at")->fetchAll();
$fields=['name'=>'Tên sản phẩm','family'=>'ProductGroup / alias','flow'=>'Flow','testPlan'=>'Distributed Test Plan','engineeringTestPlan'=>'Engineering Test Plan','dpmsTestPlan'=>'DPMS Finish Test Plan','fluxPartNumber'=>'Flux Part #','pastePartNumber'=>'Paste Part #','proflowPartNumber'=>'Proflow Part #','stencilPartNumber'=>'Stencil PB/MP #','capacitorInfo'=>'Tụ / feeder / nozzle','fluxCenter'=>'Flux Center / cân Flux','setupProcess'=>'Quy trình setup','commonIssues'=>'Lỗi thường gặp','operatorTips'=>'Mẹo xử lý','note'=>'Ghi chú'];
?><!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>CAM Product Admin</title><style>body{font:14px system-ui;margin:0;background:#07121f;color:#dceaf2}header{position:sticky;top:0;background:#0b1b2c;padding:14px 4vw;display:flex;justify-content:space-between;align-items:center;z-index:2}main{max-width:1200px;margin:auto;padding:20px}.grid{display:grid;grid-template-columns:minmax(250px,350px) 1fr;gap:18px}.panel{background:#102235;border:1px solid #243f55;border-radius:14px;padding:16px;margin-bottom:15px}a{color:#6de7ef;text-decoration:none}.products a{display:block;padding:9px;border-bottom:1px solid #294054}.products small{color:#89a1b1}label{display:block;margin:10px 0;color:#91aabc;font-weight:700}input,select,textarea{box-sizing:border-box;width:100%;padding:10px;background:#071827;border:1px solid #34526a;border-radius:8px;color:#fff}textarea{min-height:82px;resize:vertical}button{padding:10px 16px;border:0;border-radius:8px;background:#22c2cb;font-weight:800}.danger{background:#c6525c;color:#fff}.msg{padding:10px;border-radius:8px;background:#163c38}.error{background:#49242a}.trial{border-color:#765b2b;background:#2b2619}.trial b{color:#ffd27d}.pending-row{display:flex;justify-content:space-between;gap:10px;padding:10px 0;border-bottom:1px solid #294054}.pending-row form{flex:0 0 auto}@media(max-width:760px){.grid{grid-template-columns:1fr}}</style><header><b>CAM PRODUCT ADMIN</b><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(cam_csrf())?>"><button name="logout">Đăng xuất</button></form></header><main><?php if($notice):?><p class="msg"><?=htmlspecialchars($notice)?></p><?php endif;?><?php if($error):?><p class="msg error"><?=htmlspecialchars($error)?></p><?php endif;?><?php if($pendingChanges):?><section class="panel trial"><h2>Bản thử nghiệm đang chờ (<?=count($pendingChanges)?>)</h2><p>API và app vẫn dùng revision hiện tại. Khi đủ 24 giờ, lần đồng bộ kế tiếp sẽ tự áp dụng.</p><?php foreach($pendingChanges as $p):?><div class="pending-row"><span><b><?=htmlspecialchars($p['name'])?></b><br>Áp dụng sau: <?=htmlspecialchars($p['effective_at'])?><br><small><?=htmlspecialchars($p['change_note'])?></small></span><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(cam_csrf())?>"><input type="hidden" name="pending_id" value="<?=intval($p['pending_id'])?>"><button class="danger" name="cancel_pending">Hủy</button></form></div><?php endforeach;?></section><?php endif;?><div class="grid"><section class="panel products"><h2><?=count($products)?> sản phẩm</h2><p><a href="/">← Mở ứng dụng</a> · <a href="/api/catalog.php" target="_blank">API JSON</a></p><?php foreach($products as $p):?><a href="?product=<?=urlencode($p['id'])?>"><b><?=htmlspecialchars($p['name'])?></b><br><small><?=htmlspecialchars($p['family'])?> · rev <?=intval($p['revision'])?></small></a><?php endforeach;?></section><section class="panel"><?php if(!$edit):?><h2>Chọn một sản phẩm để cập nhật</h2><p>Bản sửa được giữ ở chế độ thử nghiệm trong 24 giờ trước khi tự động ghi vào database public.</p><?php else:?><h2><?=htmlspecialchars($edit['name']??$selected)?> · rev <?=intval($edit['_revision'])?></h2><?php if($pendingForSelected):?><p class="msg trial"><b>Đang xem bản thử nghiệm.</b> Sẽ áp dụng sau <?=htmlspecialchars($pendingForSelected['effective_at'])?>. Lưu lại sẽ bắt đầu lại thời gian 24 giờ.</p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(cam_csrf())?>"><input type="hidden" name="id" value="<?=htmlspecialchars($selected)?>"><?php foreach($fields as $key=>$label):?><label><?=htmlspecialchars($label)?><?php if(in_array($key,['capacitorInfo','fluxCenter','setupProcess','commonIssues','operatorTips','note'],true)):?><textarea name="<?=htmlspecialchars($key)?>"><?=htmlspecialchars((string)($edit[$key]??''))?></textarea><?php elseif($key==='flow'):?><select name="flow"><?php foreach(['both','split','passives','die'] as $flow):?><option value="<?=$flow?>" <?=($edit['flow']??'')===$flow?'selected':''?>><?=$flow?></option><?php endforeach;?></select><?php else:?><input name="<?=htmlspecialchars($key)?>" value="<?=htmlspecialchars((string)($edit[$key]??''))?>"><?php endif;?></label><?php endforeach;?><label>Ghi chú lần sửa<input name="change_note" required placeholder="Nguồn xác minh và lý do sửa"></label><button name="save_product">Bắt đầu thử nghiệm 24 giờ</button></form><?php endif;?></section></div></main></html>
